contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newRate) public payable {
        // Ensure the test contract is the current owner so setRewardRate does not revert.
        c.changeOwner(address(this));

        // Perform the state-changing call directly as a top-level statement.
        try c.setRewardRate(newRate) {
            // If the call succeeded, the public getter must return exactly the new value.
            assert(c.rewardRate() == newRate);
        } catch {
            // If the call reverted, the function should not have changed the state.
            // But since we set ourselves as owner, it should not revert.
            assert(false);
        }
    }

    receive() external payable {}
}

