contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "zero recipient");
        require(amount > 0, "zero amount");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        require(senderBefore >= amount, "insufficient sender balance");

        bool reverted;
        try c.transfer(recipient, amount) returns (bool ok) {
            reverted = !ok;
        } catch {
            reverted = true;
        }

        assert(reverted || c.balanceOf(address(this)) <= senderBefore - amount);
    }

    receive() external payable {}
}

