    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public payable {
        address beforeOwner = c.owner();
        bool callerIsOwner = (caller == beforeOwner);
        bool reverted;
        try c.changeOwner(newOwner) { reverted = false; } catch { reverted = true; }
        assert(reverted == !callerIsOwner);
    }

    receive() external payable {}
}

