        uint256 t;
        bool ok = false;
        try c.tokenFromReflection(r) returns (uint256 _t) {
            t = _t;
            ok = true;
        } catch {
            ok = false;
        }

        uint256 rate = rTotal / tSupply;

        assert(ok ? (r >= t * rate && r < (t + 1) * rate) : r > rTotal);
    }

    receive() external payable {}
}

