contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newMin, uint256 probe) public payable {
        require(probe <= newMin, "probe must not exceed newMin");

        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeOwner = uint256(uint160(c.owner()));

        bool reverted;
        try c.setMinTxnAmount(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterMin = c.minTxnAmount();
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterOwner = uint256(uint160(c.owner()));

        assert(
            !reverted &&
            afterMin == newMin &&
            afterTotalSupply == beforeTotalSupply &&
            afterOwner == beforeOwner
        );
    }

    receive() external payable {}
}
